-- Fulfillment Hub database schema + seed data
-- Generated from Karmic_Seed_Fulfillment_Dataset.xlsx
-- Fictional/dummy data for demonstration only.

CREATE DATABASE IF NOT EXISTS fulfillment_hub;
USE fulfillment_hub;

SET FOREIGN_KEY_CHECKS = 0;


DROP TABLE IF EXISTS notifications;
DROP TABLE IF EXISTS order_status_history;
DROP TABLE IF EXISTS exceptions;
DROP TABLE IF EXISTS shipments;
DROP TABLE IF EXISTS staging;
DROP TABLE IF EXISTS packing;
DROP TABLE IF EXISTS picking;
DROP TABLE IF EXISTS warehouse_transfers;
DROP TABLE IF EXISTS order_items;
DROP TABLE IF EXISTS orders;
DROP TABLE IF EXISTS inventory;
DROP TABLE IF EXISTS couriers;
DROP TABLE IF EXISTS warehouses;
DROP TABLE IF EXISTS products;
DROP TABLE IF EXISTS users;

CREATE TABLE users (
    user_id VARCHAR(10) PRIMARY KEY,
    name VARCHAR(100) NOT NULL,
    role ENUM('Admin','Office','Warehouse','Analyst') NOT NULL,
    email VARCHAR(150) NOT NULL UNIQUE,
    password_hash VARCHAR(255) NOT NULL
) ENGINE=InnoDB;

CREATE TABLE products (
    product_id VARCHAR(10) PRIMARY KEY,
    product_name VARCHAR(150) NOT NULL,
    category VARCHAR(80) NOT NULL,
    variant VARCHAR(80) NOT NULL,
    unit_price DECIMAL(10,2) NOT NULL,
    reorder_level INT NOT NULL DEFAULT 0,
    active ENUM('Yes','No') NOT NULL DEFAULT 'Yes'
) ENGINE=InnoDB;

CREATE TABLE warehouses (
    warehouse_id VARCHAR(10) PRIMARY KEY,
    warehouse_name VARCHAR(100) NOT NULL,
    location VARCHAR(100) NOT NULL,
    warehouse_type ENUM('Primary','Secondary') NOT NULL,
    active ENUM('Yes','No') NOT NULL DEFAULT 'Yes'
) ENGINE=InnoDB;

CREATE TABLE inventory (
    inventory_id VARCHAR(10) PRIMARY KEY,
    warehouse_id VARCHAR(10) NOT NULL,
    product_id VARCHAR(10) NOT NULL,
    available_qty INT NOT NULL DEFAULT 0,
    reserved_qty INT NOT NULL DEFAULT 0,
    reorder_level INT NOT NULL DEFAULT 0,
    stock_status VARCHAR(20) NOT NULL DEFAULT 'Healthy',
    FOREIGN KEY (warehouse_id) REFERENCES warehouses(warehouse_id),
    FOREIGN KEY (product_id) REFERENCES products(product_id),
    UNIQUE KEY uniq_wh_product (warehouse_id, product_id)
) ENGINE=InnoDB;

CREATE TABLE couriers (
    courier_id VARCHAR(10) PRIMARY KEY,
    courier_name VARCHAR(100) NOT NULL,
    service_type VARCHAR(50) NOT NULL,
    pickup_cutoff VARCHAR(10) NOT NULL,
    avg_delivery_days INT NOT NULL,
    cost_per_shipment DECIMAL(10,2) NOT NULL
) ENGINE=InnoDB;

CREATE TABLE orders (
    order_id VARCHAR(10) PRIMARY KEY,
    customer_name VARCHAR(120) NOT NULL,
    order_date DATETIME NOT NULL,
    priority VARCHAR(20) NOT NULL DEFAULT 'Normal',
    priority_deadline DATETIME NOT NULL,
    warehouse_id VARCHAR(10) NOT NULL,
    order_status VARCHAR(30) NOT NULL DEFAULT 'Order Received',
    total_amount DECIMAL(10,2) NOT NULL DEFAULT 0,
    payment_status VARCHAR(20) NOT NULL DEFAULT 'Paid',
    delivery_city VARCHAR(100),
    FOREIGN KEY (warehouse_id) REFERENCES warehouses(warehouse_id),
    INDEX idx_status (order_status),
    INDEX idx_priority (priority)
) ENGINE=InnoDB;

CREATE TABLE order_items (
    order_item_id VARCHAR(10) PRIMARY KEY,
    order_id VARCHAR(10) NOT NULL,
    product_id VARCHAR(10) NOT NULL,
    quantity INT NOT NULL,
    unit_price DECIMAL(10,2) NOT NULL,
    line_total DECIMAL(10,2) NOT NULL,
    variant_verified ENUM('Yes','No') NOT NULL DEFAULT 'No',
    FOREIGN KEY (order_id) REFERENCES orders(order_id) ON DELETE CASCADE,
    FOREIGN KEY (product_id) REFERENCES products(product_id),
    INDEX idx_order (order_id)
) ENGINE=InnoDB;

CREATE TABLE warehouse_transfers (
    transfer_id VARCHAR(10) PRIMARY KEY,
    product_id VARCHAR(10) NOT NULL,
    from_warehouse_id VARCHAR(10) NOT NULL,
    to_warehouse_id VARCHAR(10) NOT NULL,
    quantity INT NOT NULL,
    requested_at DATETIME NOT NULL,
    status VARCHAR(20) NOT NULL DEFAULT 'Requested',
    received_at DATETIME NULL,
    requested_by VARCHAR(10),
    reason VARCHAR(255),
    FOREIGN KEY (product_id) REFERENCES products(product_id),
    FOREIGN KEY (from_warehouse_id) REFERENCES warehouses(warehouse_id),
    FOREIGN KEY (to_warehouse_id) REFERENCES warehouses(warehouse_id)
) ENGINE=InnoDB;

CREATE TABLE picking (
    picking_id VARCHAR(10) PRIMARY KEY,
    order_id VARCHAR(10) NOT NULL,
    picker VARCHAR(100),
    started_at DATETIME NULL,
    completed_at DATETIME NULL,
    status VARCHAR(20) NOT NULL DEFAULT 'Pending',
    verification_result VARCHAR(50),
    FOREIGN KEY (order_id) REFERENCES orders(order_id) ON DELETE CASCADE,
    INDEX idx_order (order_id)
) ENGINE=InnoDB;

CREATE TABLE packing (
    packing_id VARCHAR(10) PRIMARY KEY,
    order_id VARCHAR(10) NOT NULL,
    box_id VARCHAR(20),
    packed_by VARCHAR(100),
    packed_at DATETIME NULL,
    package_type VARCHAR(50),
    label_status VARCHAR(30) DEFAULT 'Pending',
    status VARCHAR(20) NOT NULL DEFAULT 'Pending',
    FOREIGN KEY (order_id) REFERENCES orders(order_id) ON DELETE CASCADE,
    INDEX idx_order (order_id)
) ENGINE=InnoDB;

CREATE TABLE staging (
    staging_id VARCHAR(10) PRIMARY KEY,
    order_id VARCHAR(10) NOT NULL,
    box_id VARCHAR(20),
    staging_location VARCHAR(30),
    courier_id VARCHAR(10),
    staged_at DATETIME NULL,
    scheduled_pickup DATETIME NULL,
    pickup_status VARCHAR(20) NOT NULL DEFAULT 'Waiting',
    status VARCHAR(30) DEFAULT 'Staged',
    FOREIGN KEY (order_id) REFERENCES orders(order_id) ON DELETE CASCADE,
    FOREIGN KEY (courier_id) REFERENCES couriers(courier_id),
    INDEX idx_order (order_id)
) ENGINE=InnoDB;

CREATE TABLE shipments (
    shipment_id VARCHAR(10) PRIMARY KEY,
    order_id VARCHAR(10) NOT NULL,
    courier_id VARCHAR(10),
    tracking_number VARCHAR(50),
    shipped_at DATETIME NULL,
    expected_delivery DATE NULL,
    delivered_at DATETIME NULL,
    shipment_status VARCHAR(20) NOT NULL DEFAULT 'Not Shipped',
    FOREIGN KEY (order_id) REFERENCES orders(order_id) ON DELETE CASCADE,
    FOREIGN KEY (courier_id) REFERENCES couriers(courier_id),
    INDEX idx_order (order_id)
) ENGINE=InnoDB;

CREATE TABLE exceptions (
    exception_id VARCHAR(10) PRIMARY KEY,
    order_id VARCHAR(10) NOT NULL,
    exception_type VARCHAR(50) NOT NULL,
    description VARCHAR(255),
    reported_at DATETIME NOT NULL,
    reported_by VARCHAR(10),
    assigned_to VARCHAR(10),
    priority VARCHAR(20) NOT NULL DEFAULT 'Medium',
    status VARCHAR(20) NOT NULL DEFAULT 'Open',
    resolution VARCHAR(255),
    FOREIGN KEY (order_id) REFERENCES orders(order_id) ON DELETE CASCADE,
    INDEX idx_status (status)
) ENGINE=InnoDB;

CREATE TABLE order_status_history (
    history_id VARCHAR(12) PRIMARY KEY,
    order_id VARCHAR(10) NOT NULL,
    status VARCHAR(30) NOT NULL,
    changed_at DATETIME NOT NULL,
    changed_by VARCHAR(10),
    notes VARCHAR(255),
    FOREIGN KEY (order_id) REFERENCES orders(order_id) ON DELETE CASCADE,
    INDEX idx_order (order_id)
) ENGINE=InnoDB;

CREATE TABLE notifications (
    notification_id VARCHAR(10) PRIMARY KEY,
    notification_type VARCHAR(100),
    order_id VARCHAR(10),
    created_at DATETIME NOT NULL,
    severity ENUM('Low','Medium','High') NOT NULL DEFAULT 'Low',
    message VARCHAR(255),
    status ENUM('Unread','Read') NOT NULL DEFAULT 'Unread',
    target_role VARCHAR(30),
    FOREIGN KEY (order_id) REFERENCES orders(order_id) ON DELETE SET NULL
) ENGINE=InnoDB;

